            var selector = ".mp_wm_page, .mp_wm_page .nav_container, .mp_wm_page .nav_content, .mp_wm_page .nav_list_sec, .mp_wm_page .nav_list_section, .mp_wm_page .nav_img_sec, .mp_wm_page .nav_image_sec, .mp_wm_page .nav_img_section, .mp_wm_page .nav_image_section";
            var nodes = [];
