        function hasGroupedTextAncestor(node, groupedNodes) {
          if (!(node instanceof HTMLElement)) {
            return false;
          }
          var parent = node.parentElement;
          while (parent && parent !== document.body) {
            if (Array.isArray(groupedNodes) && groupedNodes.indexOf(parent) >= 0) {
              return true;
            }
            parent = parent.parentElement;
          }
          return false;
        }

        function groupedNodeContainsLinks(node) {
          if (!(node instanceof HTMLElement)) {
            return false;
          }
          return Boolean(node.querySelector("a[href], a[data-zw-inline-type='link'], a"));
        }

        function hasLinkAncestor(node) {
          if (!(node instanceof HTMLElement)) {
            return false;
          }
          var parent = node.parentElement;
          while (parent && parent !== document.body) {
            if (String(parent.tagName || "").toLowerCase() === "a") {
              return true;
            }
            parent = parent.parentElement;
          }
          return false;
        }

