  // ── Workbench In-Page Mode Picker & Switcher ──────────────────────────────

  /** Tracks whether the user has chosen a mode in the current workbench session */
  let _wbModeChosen = false;

  /**
   * Show the floating mode picker overlay inside the workbench canvas.
   * Called automatically after the page iframe finishes loading.
   */
  function showWorkbenchModePicker() {
    const picker = document.getElementById("workbenchModePicker");
    if (!picker) return;
    // Don't show if the workbench is already closed or mode was already picked
    if (!el.workbench || el.workbench.classList.contains("hidden")) return;
    if (_wbModeChosen) return;
    picker.classList.remove("hidden");
    picker.removeAttribute("aria-hidden");
  }

  function hideWorkbenchModePicker() {
    const picker = document.getElementById("workbenchModePicker");
    if (picker) {
      picker.classList.add("hidden");
      picker.setAttribute("aria-hidden", "true");
    }
  }

  /**
   * Show the segmented mode switcher (Edit | Animate) in the workbench header.
   * Called once the user has chosen a mode.
   * @param {"edit"|"animate"} activeMode
   */
  function showWorkbenchModeSwitcher(activeMode) {
    const switcher = document.getElementById("workbenchModeSwitcher");
    if (!switcher) return;
    switcher.classList.remove("hidden");
    // Sync pressed states
    const editBtn = document.getElementById("workbenchModeSwitchEdit");
    const animBtn = document.getElementById("workbenchModeSwitchAnim");
    if (editBtn) editBtn.setAttribute("aria-pressed", activeMode === "edit" ? "true" : "false");
    if (animBtn) animBtn.setAttribute("aria-pressed", activeMode === "animate" ? "true" : "false");
    // Also hide the legacy animModeNavBtn so there's no double button
    const legacyAnimBtn = document.getElementById("animModeNavBtn");
    if (legacyAnimBtn) legacyAnimBtn.style.display = "none";
  }

  function hideWorkbenchModeSwitcher() {
    const switcher = document.getElementById("workbenchModeSwitcher");
    if (switcher) switcher.classList.add("hidden");
    // Restore legacy animModeNavBtn visibility
    const legacyAnimBtn = document.getElementById("animModeNavBtn");
    if (legacyAnimBtn) legacyAnimBtn.style.display = "";
  }

  /**
   * Called when the user picks a mode from the picker or switcher.
   * Activates the chosen mode and updates UI state.
   * @param {"edit"|"animate"} mode
   */
  function switchWorkbenchMode(mode) {
    _wbModeChosen = true;
    hideWorkbenchModePicker();

    if (mode === "animate") {
      // Enter animation mode
      if (!_animModeActive) {
        if (typeof enterAnimationMode === "function") {
          enterAnimationMode();
        }
      }
      showWorkbenchModeSwitcher("animate");
    } else {
      // Switch to page edit mode
      if (_animModeActive) {
        if (typeof exitAnimationMode === "function") {
          exitAnimationMode();
        }
      }
      showWorkbenchModeSwitcher("edit");
    }
  }

  /**
   * Wire up all events for the in-workbench mode picker and header switcher.
   */
  function wireWorkbenchModePickerEvents() {
    const editPickerBtn  = document.getElementById("workbenchModePickerEdit");
    const animPickerBtn  = document.getElementById("workbenchModePickerAnimate");
    const editSwitchBtn  = document.getElementById("workbenchModeSwitchEdit");
    const animSwitchBtn  = document.getElementById("workbenchModeSwitchAnim");

    if (editPickerBtn) {
      editPickerBtn.addEventListener("click", () => switchWorkbenchMode("edit"));
    }
    if (animPickerBtn) {
      animPickerBtn.addEventListener("click", () => switchWorkbenchMode("animate"));
    }
    if (editSwitchBtn) {
      editSwitchBtn.addEventListener("click", () => {
        if (_animModeActive) switchWorkbenchMode("edit");
      });
    }
    if (animSwitchBtn) {
      animSwitchBtn.addEventListener("click", () => {
        if (!_animModeActive) switchWorkbenchMode("animate");
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", wireWorkbenchModePickerEvents, { once: true });
  } else {
    wireWorkbenchModePickerEvents();
  }

