  // ── Product Dashboard ─────────────────────────────────────────────────────

  let _dashboardScanCache = null; // { productId, lang, results }

  function openDashboardModal() {
    const modal = document.getElementById("dashboardModal");
    if (!modal) return;
    modal.classList.remove("hidden");
    modal.setAttribute("aria-hidden", "false");

    const productId = state.activeProduct || "";
    const lang = state.activeLanguage || "en";
    const languageMap = state.productPages.get(productId) || new Map();
    const urls = (languageMap.get(lang) || languageMap.get("en") || []).slice();

    const labelEl = document.getElementById("dashboardProductLabel");
    if (labelEl) {
      const productName = (state.products || []).find(function(p) { return p.id === productId; });
      labelEl.textContent = (productName && productName.name) ? productName.name : productId;
    }

    // Use cache if same product+lang
    if (
      _dashboardScanCache
      && _dashboardScanCache.productId === productId
      && _dashboardScanCache.lang === lang
    ) {
      renderDashboard(_dashboardScanCache.results, urls.length);
      return;
    }

    showDashboardLoading();
    runDashboardScan(urls, productId, lang);
  }

  function closeDashboardModal() {
    const modal = document.getElementById("dashboardModal");
    if (!modal) return;
    modal.classList.add("hidden");
    modal.setAttribute("aria-hidden", "true");
  }

  function showDashboardLoading() {
    const body = document.getElementById("dashboardBody");
    if (!body) return;
    body.innerHTML = `
      <div class="dashboard-loading">
        <div class="dashboard-loading-spinner"></div>
        <p id="dashboardLoadingText">Starting audit…</p>
      </div>`;
  }

  async function runDashboardScan(urls, productId, lang) {
    const CONCURRENCY = 4;
    const results = [];

    // Process in batches
    for (let i = 0; i < urls.length; i += CONCURRENCY) {
      const batch = urls.slice(i, i + CONCURRENCY);
      const settled = await Promise.allSettled(batch.map(function(url) {
        return scanSinglePageForDashboard(url);
      }));
      for (let j = 0; j < settled.length; j++) {
        if (settled[j].status === "fulfilled") {
          results.push(settled[j].value);
        } else {
          results.push({ url: batch[j], error: true });
        }
      }
      // Update loading progress
      const loadEl = document.getElementById("dashboardLoadingText");
      if (loadEl) {
        const done = Math.min(i + CONCURRENCY, urls.length);
        const pct = Math.round((done / urls.length) * 100);
        loadEl.textContent = "Auditing pages… " + done + " / " + urls.length + " (" + pct + "%)";
      }
    }

    _dashboardScanCache = { productId, lang, results };
    renderDashboard(results, urls.length);
  }

